def rd(s): return np.array([[float(v) for v in r.split(',')] for r in s.split()])
c, d = rd(C), rd(D)
d[:, 0] = d[:, 0] - 80.48 + 72.52
for name, a in (('before the freeze', c), ('after it', d), ('both', np.concatenate([c, d]))):
    t = a[:, 0] - 71.6
    py = np.polyfit(t, a[:, 2], 2); px = np.polyfit(t, a[:, 1], 2)
    ry = a[:, 2] - np.polyval(py, t)
    print(name, 'y: accel %.1f px/vs2, apex at %.2f, rms %.2f px | x: speed %.0f px/vs, accel %.1f' % (2*py[0], 71.6 - py[1]/(2*py[0]), ry.std(), px[1], 2*px[0]))
a_px = 2*np.polyfit(np.concatenate([c, d])[:, 0], np.concatenate([c, d])[:, 2], 2)[0]
for pxm in (360, 388, 415, 440):
    for pitch in (8, 12):
        print('px/m %d pitch %d -> k = %.2f' % (pxm, pitch, np.sqrt(9.81*np.cos(np.radians(pitch))*pxm/a_px)))

from scipy.optimize import least_squares
a = np.concatenate([c, d]); t = a[:, 0] - 71.6
tc = (72.52 + (81.42 - 80.48)) - 71.6   # contact, in moving time
def res(p, sel=slice(None)):
    a0, a1, b0, b1, b2, e = p
    den = 1 + e * t[sel]
    return np.concatenate([(a0 + a1 * t[sel]) / den - (a[sel, 1] - 960), (b0 + b1 * t[sel] + b2 * t[sel] ** 2) / den - (a[sel, 2] - 540)])
for name, sel in (('all', slice(None)), ('before the freeze', slice(0, len(c)))):
    r = least_squares(res, [230, -210, 73, 0, 45, 0.0], args=(sel,))
    a0, a1, b0, b1, b2, e = r.x
    n = len(t[sel])
    print(name, 'e %.3f per vs (depth x%.2f by contact), b2 %.1f, rms x %.2f y %.2f px' % (e, 1 + e * tc, b2, r.fun[:n].std(), r.fun[n:].std()))
    for pxm_player in (372, 400, 430):
        pxm0 = pxm_player * (1 + e * tc)
        print('   player %d px/m at contact -> ball %d px/m at the apex -> k = %.2f' % (pxm_player, pxm0, np.sqrt(9.81 * np.cos(np.radians(10)) * pxm0 / (2 * b2))))
